function defaultSleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Call `operation` until it resolves.
 *
 * Failed attempts are followed by an exponentially increasing delay
 * (`baseDelayMs * 2 ** (attempt - 1)`), capped at `maxDelayMs`.
 */
export async function retry(operation, options = {}) {
  const maxAttempts = options.maxAttempts ?? 3;
  const baseDelayMs = options.baseDelayMs ?? 10;
  const maxDelayMs = options.maxDelayMs ?? 1000;
  const sleep = options.sleep ?? defaultSleep;
  let last;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await operation(attempt);
    } catch (error) {
      last = error;
      if (attempt < maxAttempts) {
        await sleep(Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs));
      }
    }
  }
  throw new RetriesExhausted(maxAttempts, last);
}

