  const started = Date.now();
  await assert.rejects(
    () => retry(() => Promise.reject(new Error('always')), { maxAttempts: 4 }),
    RetriesExhausted,
  );
  assert.ok(
    Date.now() - started < 250,
    `four attempts took ${Date.now() - started}ms, over the 250ms budget`,
  );
});

