test('backs off exponentially between attempts', async () => {
  const delays = [];
  const sleep = async (ms) => {
    delays.push(ms);
  };
  await assert.rejects(
    () =>
      retry(() => Promise.reject(new Error('always')), {
        maxAttempts: 4,
        baseDelayMs: 10,
        sleep,
      }),
    RetriesExhausted,
  );
  assert.deepEqual(delays, [10, 20, 40]);
});

test('caps the backoff delay', async () => {
  const delays = [];
  const sleep = async (ms) => {
    delays.push(ms);
  };
  await assert.rejects(
    () =>
      retry(() => Promise.reject(new Error('always')), {
        maxAttempts: 5,
        baseDelayMs: 10,
        maxDelayMs: 25,
        sleep,
      }),
    RetriesExhausted,
  );
  assert.deepEqual(delays, [10, 20, 25, 25]);
});

